<?php
namespace qqworld_collector\module\collect_filter; use voku\helper\HtmlDomParser; class filter_by_selector extends filter { public function wipe($item, $selectors) { if (!empty($selectors)) { $GLOBALS['QC']->collector->engine->selector->inlucdes(); if ( $this->options->qc_collection_project_core == 'querylist' ) { $dom = $GLOBALS['QC']->collector->engine->selector->ql->html('<div><div class="qqworld-filter-by-selector-wrap">' . $item . '</div></div>'); foreach ($selectors as $selector) { $selector = html_entity_decode($selector); $preg = preg_match('/:eq\(([\-\d]*)\)/i', $selector, $match); if ($preg) { $selector = preg_replace('/:eq\(([\-\d]*)\)/i', '', $selector); $index = (int) $match[1]; if ($index < 0) { $length = $dom->find('div.qqworld-filter-by-selector-wrap')->find($selector)->length(); $index = $length + $index; } $dom->find('div.qqworld-filter-by-selector-wrap')->find($selector)->eq($index)->remove(); } else { $dom->find('div.qqworld-filter-by-selector-wrap')->find($selector)->remove(); } } $item = $dom->find('div.qqworld-filter-by-selector-wrap')->html(); } else { $dom = HtmlDomParser::str_get_html($item); foreach ($selectors as $selector) { $selector = html_entity_decode($selector); $preg = preg_match('/:eq\(([\-\d]*)\)/i', $selector, $match); if ($preg) { $selector = preg_replace('/:eq\(([\-\d]*)\)/i', '', $selector); $index = (int) $match[1]; if ($index < 0) { $length = count($dom->find($selector)); $index = $length + $index; } $dom->find($selector, $index)->outertext = ""; } else { $indexs = []; foreach ($dom->find($selector) as $index => $element) { $indexs[] = $index; } $indexs = array_reverse($indexs); foreach ($indexs as $index) { $dom->find($selector, $index)->outertext = ""; } } } $item = $dom->save(); } } return $item; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { $selectors = explode("\n", $args); $selectors = array_filter($selectors, array($this, 'is_not_empty')); $item = $this->wipe($item, $selectors); } return $item; } } ?>